import{_ as e,o as n,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"💡 学习建议","description":"先把 Agent 的\\"循环\\"画出来:状态 / 节点 / 边先画在纸上,再写代码,能省掉一半的调试","frontmatter":{},"headers":[],"relativePath":"agent/学习计划/项目B-Agent工作台/14-study-tips.md","filePath":"agent/学习计划/项目B-Agent工作台/14-study-tips.md","lastUpdated":1793932732000}'),r={name:"agent/学习计划/项目B-Agent工作台/14-study-tips.md"};function i(s,t,l,g,d,_){return n(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="💡-学习建议" tabindex="-1">💡 学习建议 <a class="header-anchor" href="#💡-学习建议" aria-label="Permalink to &quot;💡 学习建议&quot;">​</a></h1><ol><li><strong>先把 Agent 的&quot;循环&quot;画出来</strong>:状态 / 节点 / 边先画在纸上,再写代码,能省掉一半的调试</li><li><strong>工具返回值要控制长度</strong>:模型上下文有限,工具返回原始数据等于自杀,要做裁剪和摘要</li><li><strong>工具要有超时和重试上限</strong>:无限重试的 Agent 会烧钱</li><li><strong>断点续跑比一气呵成更重要</strong>:持久化做不好,长任务一崩就全白跑</li><li><strong>Human-in-the-Loop 尽早接上</strong>:等写完再补人工确认,会发现状态模型要重写</li><li>完成后回 <a href="/agent/学习计划/9-学习进度跟踪">进度跟踪页</a> 打卡</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>核心建议:<strong>先画出状态图再写代码</strong>;每个节点单独用假数据测通;<strong>先做单工具再拆多工具</strong>。</li><li>调试技巧:把每一步的 State 打出来看,比读代码更快定位问题。</li><li>一定要自己踩一次「工具参数不合法」「死循环」「上下文超长」的坑,这些是面试高频追问。</li><li>建议录一段<strong>多轮工具调用的完整日志</strong>,复盘时能看清每步的 token 与决策。</li><li>面试加分:讲「<strong>我调工具时发现模型经常选错,于是重写了工具的 description 并分组,准确率明显提升</strong>」。</li></ul>',4)])])}const u=e(r,[["render",i]]);export{p as __pageData,u as default};
